#!/usr/bin/env python3
"""ByteOracle CLI with --json output support."""

import argparse
import json
from pathlib import Path
from typing import Any

TEXT_EXTENSIONS = {
    ".txt", ".py", ".js", ".ts", ".json", ".md", ".csv",
    ".html", ".css", ".xml", ".yaml", ".yml", ".toml",
    ".sh", ".bash", ".rb", ".java", ".c", ".cpp", ".h",
}


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="ByteOracle file type detector")
    parser.add_argument("paths", nargs="*", help="Files or directories to analyze")
    parser.add_argument("--json", action="store_true", help="Output results as JSON")
    return parser.parse_args(argv)


def _analyze_file(path: str) -> dict[str, Any] | None:
    """Analyze a single file and return result dict, or None on error."""
    try:
        with open(path, "rb") as f:
            content = f.read()
    except (OSError, IOError):
        return None

    ext = Path(path).suffix.lower()
    is_text = b"\x00" not in content
    detected_type = "text" if is_text else "binary"
    expected_type = "text" if ext in TEXT_EXTENSIONS else "binary"
    mismatch = detected_type != expected_type

    return {
        "path": path,
        "extension": ext,
        "detected_type": detected_type,
        "mismatch": mismatch,
    }


def detect_files(paths: list[str]) -> list[dict[str, Any]]:
    """Detect file types for given paths (files or directories)."""
    results = []
    for path in paths:
        p = Path(path)
        if p.is_dir():
            for child in sorted(p.iterdir()):
                if child.is_file():
                    result = _analyze_file(str(child))
                    if result is not None:
                        results.append(result)
        elif p.is_file():
            result = _analyze_file(path)
            if result is not None:
                results.append(result)
    return results


def format_json(results: list[dict[str, Any]]) -> str:
    """Format detection results as a JSON string."""
    return json.dumps(results)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    results = detect_files(args.paths)
    if args.json:
        print(format_json(results))
    else:
        for r in results:
            status = "MISMATCH" if r["mismatch"] else "OK"
            print(f"{r['path']}: {r['detected_type']} [{status}]")
    return 0


if __name__ == "__main__":
    main()

"""Core file-type detection engine with text/binary heuristic."""

from .signatures import match_signature

MAGIC_SIZE = 8192

# Printable ASCII + common whitespace (tab, newline, carriage return)
_PRINTABLE = set(range(32, 127)) | {9, 10, 13}


def is_text(data: bytes) -> bool:
    """Heuristic that decides whether *data* looks like text.

    A file is considered **text** when both conditions hold:

    1. No null byte (``\x00``) appears in the data — null bytes are a
       strong indicator of binary content.
    2. At least 70 % of non-whitespace characters are printable ASCII.

    Returns ``True`` for text-like data, ``False`` for binary-like data.
    """
    # Null-byte check
    if b"\x00" in data:
        return False

    # Printable-character ratio (ignore whitespace)
    non_ws = 0
    printable = 0
    for byte_val in data:
        if byte_val not in (9, 10, 13, 32):  # skip whitespace
            non_ws += 1
            if byte_val in _PRINTABLE:
                printable += 1

    if non_ws == 0:                       # empty or all-whitespace → text
        return True

    return (printable / non_ws) >= 0.7


def detect(filepath):
    """Detect the type of a file at *filepath*.

    Returns a dict with two keys:

    - ``type``: detected MIME-like string (e.g. ``"image/png"``,
      ``"text"``, ``"binary"``, ``"empty"``, ``"unknown"``)
    - ``method``: how the result was obtained — ``"signature"`` or
      ``"heuristic"`` (or ``"error"`` on I/O failure).
    """
    try:
        with open(filepath, "rb") as fh:
            data = fh.read(MAGIC_SIZE)
    except OSError:
        return {"type": "unknown", "method": "error"}

    if not data:
        return {"type": "empty", "method": "heuristic"}

    # 1. Signature match (fast, authoritative)
    sig_type = match_signature(data)
    if sig_type is not None:
        return {"type": sig_type, "method": "signature"}

    # 2. Text / binary heuristic fallback
    if is_text(data):
        return {"type": "text", "method": "heuristic"}
    return {"type": "binary", "method": "heuristic"}
